import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e as n}from"./app-42caee4a.js";const d={},t=n(`<h1 id="fastfetch-快速显示系统信息的工具-类-neofetch" tabindex="-1"><a class="header-anchor" href="#fastfetch-快速显示系统信息的工具-类-neofetch" aria-hidden="true">#</a> fastfetch（快速显示系统信息的工具（类 neofetch））</h1><blockquote><p>Homebrew 版本 2.55.1 ｜ 主页：见官方文档 ｜ 安装：<code>brew install fastfetch</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>fastfetch 是一个用 C 语言编写的高性能系统信息采集工具，在终端里以 ASCII 艺术或字符 Logo 的形式展示操作系统、内核、CPU、内存、磁盘、GPU、Shell、桌面环境等关键信息。它定位为 neofetch 的更快替代品，启动速度极快（通常只需几毫秒），非常适合在 shell 启动配置（如 <code>.bashrc</code>、<code>.zshrc</code>）中调用，或者在展示终端截图时生成美观的系统信息面板。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> fastfetch

<span class="token comment"># 升级</span>
brew upgrade fastfetch

<span class="token comment"># 卸载</span>
brew uninstall fastfetch

<span class="token comment"># 验证安装成功（查看版本号）</span>
fastfetch <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装成功后，终端里直接输入 <code>fastfetch</code> 即可显示系统信息。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>fastfetch</code></td><td>无参数，默认输出完整系统信息</td><td><code>fastfetch</code></td></tr><tr><td><code>fastfetch --logo</code></td><td>指定 logo 样式（如 <code>none</code> 隐藏 logo）</td><td><code>fastfetch --logo none</code></td></tr><tr><td><code>fastfetch --structure</code></td><td>自定义输出结构（逗号分隔的模块顺序）</td><td><code>fastfetch --structure OS:Host:CPU:GPU:Memory</code></td></tr><tr><td><code>fastfetch --format json</code></td><td>以 JSON 格式输出，便于脚本解析</td><td><code>fastfetch --format json</code></td></tr><tr><td><code>fastfetch --format jsonc</code></td><td>以 JSONC（带注释 JSON）格式输出</td><td><code>fastfetch --format jsonc</code></td></tr><tr><td><code>fastfetch --list-presets</code></td><td>列出所有内置配置预设</td><td><code>fastfetch --list-presets</code></td></tr><tr><td><code>fastfetch --preset &lt;name&gt;</code></td><td>使用指定预设配置</td><td><code>fastfetch --preset mac</code></td></tr><tr><td><code>fastfetch --config &lt;path&gt;</code></td><td>使用自定义配置文件</td><td><code>fastfetch --config ~/.config/fastfetch/config.jsonc</code></td></tr><tr><td><code>fastfetch --help</code></td><td>显示完整帮助信息</td><td><code>fastfetch --help</code></td></tr><tr><td><code>fastfetch --version</code></td><td>显示版本号</td><td><code>fastfetch --version</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-基础使用-默认输出" tabindex="-1"><a class="header-anchor" href="#示例-1-基础使用-默认输出" aria-hidden="true">#</a> 示例 1：基础使用（默认输出）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接在终端运行，查看本机系统信息</span>
fastfetch
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>运行后终端会显示类似下面的输出：操作系统、主机名、内核版本、Uptime、CPU、GPU、内存、磁盘、终端、Shell 等信息，左侧带苹果 logo（macOS 上）。</p><h3 id="示例-2-隐藏-logo-只显示信息" tabindex="-1"><a class="header-anchor" href="#示例-2-隐藏-logo-只显示信息" aria-hidden="true">#</a> 示例 2：隐藏 Logo，只显示信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 某些场景下（如脚本日志中）不需要 logo，可以隐藏</span>
fastfetch <span class="token parameter variable">--logo</span> none
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>输出将不再显示 ASCII 艺术 logo，只保留各项系统信息，适合嵌入脚本或管道处理。</p><h3 id="示例-3-以-json-格式输出供脚本解析" tabindex="-1"><a class="header-anchor" href="#示例-3-以-json-格式输出供脚本解析" aria-hidden="true">#</a> 示例 3：以 JSON 格式输出供脚本解析</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 将系统信息导出为 JSON，交给 jq 等工具处理</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token string">&#39;.host&#39;</span>           <span class="token comment"># 提取主机名等信息</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token string">&#39;.cpu&#39;</span>            <span class="token comment"># 提取 CPU 信息</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这会输出结构化的 JSON 数据，方便在 shell 脚本、CI 流程中自动化采集系统信息。</p><h3 id="示例-4-生成自定义配置文件" tabindex="-1"><a class="header-anchor" href="#示例-4-生成自定义配置文件" aria-hidden="true">#</a> 示例 4：生成自定义配置文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 首次生成默认配置文件到标准位置，然后编辑</span>
fastfetch --gen-config

<span class="token comment"># 查看生成位置（macOS/Linux 常见路径）</span>
<span class="token function">cat</span> ~/.config/fastfetch/config.jsonc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>--gen-config</code> 会在 <code>~/.config/fastfetch/config.jsonc</code> 生成一份带完整注释的默认配置，你可以在此基础上修改 logo、模块顺序、显示样式等。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-使用预设快速切换外观" tabindex="-1"><a class="header-anchor" href="#_1-使用预设快速切换外观" aria-hidden="true">#</a> 1. 使用预设快速切换外观</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看所有可用预设</span>
fastfetch --list-presets

<span class="token comment"># 使用 macOS 风格预设</span>
fastfetch <span class="token parameter variable">--preset</span> mac
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>预设文件位于 fastfetch 安装目录下的 <code>presets/</code> 目录中（可通过 <code>brew --prefix fastfetch</code> 查看安装路径）。你也可以将自己的配置以 <code>*.jsonc</code> 放入 <code>~/.config/fastfetch/</code> 目录，用 <code>--preset 文件名</code> 调用。</p><h3 id="_2-结合-shell-启动文件自动展示" tabindex="-1"><a class="header-anchor" href="#_2-结合-shell-启动文件自动展示" aria-hidden="true">#</a> 2. 结合 shell 启动文件自动展示</h3><p>在 <code>~/.zshrc</code> 或 <code>~/.bashrc</code> 末尾追加一行，登录终端时自动显示系统信息：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>fastfetch <span class="token parameter variable">--logo</span> none
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>因为 fastfetch 启动极快（毫秒级），不会明显拖慢 shell 启动速度。</p><h3 id="_3-模块结构自定义" tabindex="-1"><a class="header-anchor" href="#_3-模块结构自定义" aria-hidden="true">#</a> 3. 模块结构自定义</h3><p>配置文件中的 <code>structure</code> 字段控制显示顺序与内容，例如只显示常用模块：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>fastfetch <span class="token parameter variable">--structure</span> OS:Host:Uptime:Kernel:CPU:Memory:Shell
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>你还可以在配置文件中为每个模块单独设置颜色、标签（key）、是否显示等细节。</p><h3 id="_4-环境变量与主题色" tabindex="-1"><a class="header-anchor" href="#_4-环境变量与主题色" aria-hidden="true">#</a> 4. 环境变量与主题色</h3><p>fastfetch 支持通过环境变量调整部分行为，例如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 强制输出无颜色（用于管道或日志）</span>
<span class="token assign-left variable">NO_COLOR</span><span class="token operator">=</span><span class="token number">1</span> fastfetch

<span class="token comment"># 设置终端列数/宽度以调整 logo 缩放</span>
<span class="token assign-left variable"><span class="token environment constant">COLUMNS</span></span><span class="token operator">=</span><span class="token number">80</span> fastfetch
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>同时支持 <code>--title-color</code>、<code>--key-color</code> 等参数控制输出配色，可配合终端主题做统一风格。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-首次运行缺少字体导致-logo-错位" tabindex="-1"><a class="header-anchor" href="#_1-首次运行缺少字体导致-logo-错位" aria-hidden="true">#</a> 1. 首次运行缺少字体导致 Logo 错位</h3><p>ASCII logo 对齐依赖等宽字体。如果 logo 出现错位，先检查终端是否使用等宽字体（如 Menlo、JetBrains Mono、Fira Code），或者直接使用 <code>fastfetch --logo none</code> 跳过 logo。</p><h3 id="_2-json-输出与默认输出差异" tabindex="-1"><a class="header-anchor" href="#_2-json-输出与默认输出差异" aria-hidden="true">#</a> 2. JSON 输出与默认输出差异</h3><p><code>--format json</code> 输出的是原始数据（键名小写），与默认的人类可读输出字段并不完全一一对应。脚本解析时建议先 <code>fastfetch --format json</code> 查看实际字段名，再编写解析逻辑。</p><h3 id="_3-配置文件语法" tabindex="-1"><a class="header-anchor" href="#_3-配置文件语法" aria-hidden="true">#</a> 3. 配置文件语法</h3><p>配置文件为 JSONC（JSON with Comments）格式，支持 <code>//</code> 注释和尾逗号。如果你手动编辑时用了标准 JSON 且带注释，fastfetch 会报解析错误——务必使用 JSONC 语法。</p><h3 id="_4-性能与频率" tabindex="-1"><a class="header-anchor" href="#_4-性能与频率" aria-hidden="true">#</a> 4. 性能与频率</h3><p>fastfetch 本身很轻量，但若在 shell 启动文件中每次打开终端都运行，频繁刷新磁盘/内核信息仍会有少量开销。建议只在交互式登录 shell 中调用，不要放进非交互式脚本（可用 <code>[[ $- == *i* ]]</code> 判断）的默认路径里。</p><h3 id="_5-版本与升级" tabindex="-1"><a class="header-anchor" href="#_5-版本与升级" aria-hidden="true">#</a> 5. 版本与升级</h3><p>brew 升级后若遇到输出异常，先运行 <code>fastfetch --version</code> 确认版本。如从旧版本升级后配置不兼容，可备份后删除 <code>~/.config/fastfetch/</code> 重新生成默认配置，再按需调整。</p>`,49),c=[t];function o(i,r){return a(),s("div",null,c)}const f=e(d,[["render",o],["__file","fastfetch.html.vue"]]);export{f as default};
